def findNumOfValidWords(words: list[str], puzzles: list[str]) -> list[int]:
    from collections import Counter
    word_counts = Counter()
    for w in words:
        mask = 0
        for ch in set(w):
            mask |= (1 << (ord(ch) - ord('a')))
        if bin(mask).count('1') <= 7:
            word_counts[mask] += 1
    ans = []
    for p in puzzles:
        first = 1 << (ord(p[0]) - ord('a'))
        rest_mask = 0
        for ch in p[1:]:
            rest_mask |= (1 << (ord(ch) - ord('a')))
        count = 0
        submask = rest_mask
        while True:
            count += word_counts[submask | first]
            if submask == 0: break
            submask = (submask - 1) & rest_mask
        ans.append(count)
    return ans

